<section class="auth-layout"><div class="auth-intro"><span class="eyebrow"><?= $admin?'网站管理':'服务与需求，从这里连接' ?></span><h1><?= $admin?'管理好每一条信息':($register?'加入'.e(siteName()):'欢迎回来') ?></h1><p><?= $admin?'审核分类信息，管理城市、分类与知识内容。':'发布维修服务与求修需求，在个人中心查看审核状态。' ?></p><div class="auth-features"><span>城市分类查找</span><span>信息审核展示</span><span>维修知识查询</span></div></div><div class="panel auth-card"><h2><?= $admin?'管理员登录':($register?'注册账号':'账号登录') ?></h2><?php if($error): ?><div class="notice error" role="alert"><?= e($error) ?></div><?php endif ?><form method="post" class="stack-form"><?= csrfField() ?><label>账号<input name="username" autocomplete="username" minlength="3" maxlength="32" pattern="[A-Za-z0-9_]{3,32}" value="<?= e(input('username')) ?>" placeholder="英文字母、数字或下划线" required></label><?php if($register): ?><label>联系电话<input type="tel" name="phone" autocomplete="tel" minlength="6" maxlength="32" value="<?= e(input('phone')) ?>" placeholder="手机号或固定电话" required></label><?php endif ?><label>密码<input type="password" name="password" autocomplete="<?= $register?'new-password':'current-password' ?>" <?= $register?'minlength="8"':'' ?> maxlength="72" required></label><?php if($register): ?><label>确认密码<input type="password" name="confirm_password" autocomplete="new-password" minlength="8" maxlength="72" required></label><?php endif ?><button class="button full"><?= $register?'注册并登录':'登录' ?></button></form><?php if(!$admin): ?><p class="auth-switch"><?= $register?'已有账号？':'还没有账号？' ?><a href="<?= $register?'/deng-lu/':'/zhu-ce/' ?>"><?= $register?'去登录':'免费注册' ?></a></p><?php endif ?></div></section>
